SELECT jsonb_build_object(
'identity',jsonb_build_object('current_user',current_user,'session_user',session_user,'version',current_setting('server_version')),
'baseline',jsonb_build_object('public_rls_policies',(SELECT count(*) FROM pg_policies WHERE schemaname='public'),'public_security_definer',(SELECT count(*) FROM pg_proc WHERE pronamespace='public'::regnamespace AND prosecdef),'public_ws_rpc',(SELECT count(*) FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname LIKE 'ws_v1_%')),
'workspace_schemas',(SELECT coalesce(jsonb_agg(nspname),'[]'::jsonb) FROM pg_namespace WHERE nspname IN ('workspace','workspace_private','workspace_auth_bridge','workspace_bootstrap')),
'roles',(SELECT jsonb_agg(jsonb_build_object('name',rolname,'superuser',rolsuper,'bypassrls',rolbypassrls,'createrole',rolcreaterole)) FROM pg_roles WHERE rolname IN ('postgres','supabase_auth_admin','ws_owner','ws_runtime','ws_authz_reader')),
'installer',jsonb_build_object('auth_usage',has_schema_privilege(current_user,'auth','USAGE'),'auth_create',has_schema_privilege(current_user,'auth','CREATE'),'auth_owner_set',pg_has_role(current_user,'supabase_auth_admin','SET'),'public_create_grant',has_schema_privilege(current_user,'public','CREATE WITH GRANT OPTION'),'database_create',has_database_privilege(current_user,current_database(),'CREATE'),'users_id_references',has_column_privilege(current_user,'auth.users','id','REFERENCES')),
'auth_tables',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'installer_select',has_table_privilege(current_user,c.oid,'SELECT'),'authenticated_select',has_table_privilege('authenticated',c.oid,'SELECT'),'anon_select',has_table_privilege('anon',c.oid,'SELECT'))) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='auth' AND c.relname IN ('users','sessions')),
'session_columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'installer_select',has_column_privilege(current_user,c.oid,a.attnum,'SELECT'))) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='auth' AND c.relname='sessions' AND a.attname IN ('id','user_id','created_at','not_after')),
'data_api_role_settings',(SELECT coalesce(jsonb_agg(v.setting),'[]'::jsonb) FROM pg_roles r CROSS JOIN LATERAL unnest(r.rolconfig)v(setting) WHERE r.rolname='authenticator' AND (v.setting LIKE 'pgrst.db_schemas=%' OR v.setting LIKE 'pgrst.db_extra_search_path=%')),
'data_api_visible_settings',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',name,'setting',setting)),'[]'::jsonb) FROM pg_settings WHERE name IN ('pgrst.db_schemas','pgrst.db_extra_search_path'))
) AS metadata;
